"""Checkpoint reader: reads Entire checkpoint data from disk.

This is the ONLY module in the adapter that reads from the filesystem.
Everything else works on the parsed Pydantic models returned from here.
"""
from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from app.adapter.models import (
    Checkpoint,
    Session,
    SessionCheckpoint,
    TranscriptEntry,
)
from app.adapter.paths import (
    CHECKPOINTS_REF,
    FULL_TRANSCRIPT_FILENAME,
    entire_root,
    is_safe_session_id,
    session_metadata_dir,
    session_state_dir,
)


class CheckpointReader:
    """Reads checkpoint data from an Entire-enabled git repository.

    Does NOT import or call any code from the main CLI repository.
    All data is read by parsing on-disk files and git refs directly.

    Usage:
        reader = CheckpointReader("/path/to/repo")
        sessions = reader.list_sessions()
    """

    def __init__(self, repo_path: str | Path) -> None:
        self.repo_path = Path(repo_path).resolve()
        self._git_available: bool | None = None

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def list_sessions(self) -> list[Session]:
        """Return all sessions found in the repo."""
        sessions: list[Session] = []
        for session_id in self._list_session_dirs():
            if session := self.read_session(session_id):
                sessions.append(session)
        return sessions

    def read_session(self, session_id: str) -> Session | None:
        """Read one session by ID, including its checkpoints and transcript."""
        if not is_safe_session_id(session_id):
            return None

        meta_dir = session_metadata_dir(self.repo_path, session_id)
        if not meta_dir.is_dir():
            return None

        metadata_json = self._read_json(meta_dir / "metadata.json")
        if metadata_json is None:
            return None

        session = self._parse_session(session_id, metadata_json, meta_dir)

        # Load checkpoints from state dir
        state_dir = session_state_dir(self.repo_path)
        state_json = self._read_json(state_dir / f"{session_id}.json")
        if state_json:
            session.checkpoints = self._parse_checkpoints(state_json, session_id)

        # Load transcript
        transcript_path = meta_dir / FULL_TRANSCRIPT_FILENAME
        if transcript_path.is_file():
            session.transcript = self._read_transcript(transcript_path)

        return session

    def list_committed_checkpoints(self) -> list[Checkpoint]:
        """List all committed checkpoints from the entire/checkpoints/v1 ref.

        Falls back gracefully when git is unavailable.
        """
        if not self._is_git_available():
            return []

        try:
            import git
        except ImportError:
            return []

        try:
            repo = git.Repo(str(self.repo_path))
            ref_name = CHECKPOINTS_REF
            if ref_name not in repo.refs:
                return []

            ref = repo.refs[ref_name]
            checkpoints: list[Checkpoint] = []

            # Walk commits on the ref, newest first
            for commit in repo.iterate_commits(ref, max_count=50):
                session_id = self._trailer(commit, "Entire-Session", "")
                cp_id = self._trailer(commit, "Entire-Checkpoint", "")
                message = commit.message.strip().split("\n")[0] if commit.message else ""
                files = self._extract_files_from_commit(commit)

                cp = Checkpoint(
                    id=cp_id or commit.hexsha[:12],
                    session_id=session_id or "",
                    timestamp=datetime.fromtimestamp(commit.committed_date, tz=timezone.utc),
                    message=message,
                    commit_hash=commit.hexsha,
                    files_changed=files,
                )
                checkpoints.append(cp)

            return checkpoints
        except Exception:
            # Silently degrade: no checkpoints, not an error
            return []

    # ------------------------------------------------------------------
    # Internal: filesystem reads
    # ------------------------------------------------------------------

    def _read_json(self, path: Path) -> dict[str, Any] | None:
        """Read and parse one JSON file. Returns None on any error."""
        try:
            with open(path, encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None

    def _read_transcript(self, path: Path) -> list[TranscriptEntry]:
        """Read a full.jsonl file, one JSON object per line."""
        entries: list[TranscriptEntry] = []
        try:
            with open(path, encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        obj = json.loads(line)
                        entry = TranscriptEntry(
                            type=obj.get("type", ""),
                            role=obj.get("role", ""),
                            content=obj.get("content", ""),
                            timestamp=self._parse_timestamp(obj.get("timestamp")),
                            tool_name=obj.get("tool_use", {}).get("name") if obj.get("tool_use") else None,
                            tool_input=obj.get("tool_use", {}).get("input"),
                            is_tool_use=obj.get("type") == "input",
                            is_tool_result=obj.get("type") == "result",
                            raw=obj,
                        )
                        entries.append(entry)
                    except Exception:
                        # Skip malformed lines
                        continue
        except Exception:
            pass
        return entries

    def _read_state_file(self, session_id: str) -> dict[str, Any] | None:
        """Read the session state JSON from .git/entire-sessions/."""
        state_path = session_state_dir(self.repo_path) / f"{session_id}.json"
        return self._read_json(state_path)

    # ------------------------------------------------------------------
    # Internal: parsing helpers
    # ------------------------------------------------------------------

    def _list_session_dirs(self) -> list[str]:
        """List session IDs from .entire/metadata/."""
        root = entire_root(self.repo_path) / "metadata"
        if not root.is_dir():
            return []

        session_ids: list[str] = []
        try:
            for entry in root.iterdir():
                if entry.is_dir() and is_safe_session_id(entry.name):
                    session_ids.append(entry.name)
        except Exception:
            pass

        return session_ids

    def _parse_session(
        self, session_id: str, metadata_json: dict[str, Any], meta_dir: Path
    ) -> Session:
        """Build a Session from a metadata.json dict."""
        # Extract sessions list (may be a list or a single session object)
        sessions_data = metadata_json.get("sessions", [])
        if isinstance(sessions_data, list) and sessions_data:
            sdata = sessions_data[0]
        elif isinstance(sessions_data, dict):
            sdata = sessions_data
        else:
            sdata = metadata_json

        description = sdata.get("description", "")
        if not description:
            description = sdata.get("prompt", "")

        start_time = self._parse_timestamp(sdata.get("start_time"))
        end_time = self._parse_timestamp(sdata.get("end_time"))

        agent_type = metadata_json.get("agent", metadata_json.get("agent_type", ""))

        status = "unknown"
        if sdata.get("status") == "active":
            status = "active"
        elif end_time is not None:
            status = "ended"

        return Session(
            id=session_id,
            description=description,
            start_time=start_time,
            end_time=end_time,
            agent_type=agent_type,
            status=status,
            metadata_dir=str(meta_dir),
        )

    def _parse_checkpoints(
        self, state_json: dict[str, Any], session_id: str
    ) -> list[SessionCheckpoint]:
        """Parse checkpoint list from a session state file."""
        checkpoints: list[SessionCheckpoint] = []

        checkpoints_data = state_json.get("checkpoints", [])
        if not isinstance(checkpoints_data, list):
            checkpoints_data = []

        for i, cp_data in enumerate(checkpoints_data):
            if isinstance(cp_data, dict):
                cp = SessionCheckpoint(
                    id=cp_data.get("id", f"{session_id}-{i}"),
                    session_id=session_id,
                    timestamp=self._parse_timestamp(cp_data.get("timestamp")),
                    message=cp_data.get("message", ""),
                    commit_hash=cp_data.get("commit_hash"),
                    files_changed=cp_data.get("files_changed", []),
                    files_added=cp_data.get("files_added", []),
                    files_deleted=cp_data.get("files_deleted", []),
                    is_task_checkpoint=cp_data.get("is_task_checkpoint", False),
                    metadata_dir=cp_data.get("metadata_dir", ""),
                )
                checkpoints.append(cp)

        return checkpoints

    def _parse_timestamp(self, value: Any) -> datetime | None:
        """Parse a timestamp from various formats."""
        if value is None:
            return None
        if isinstance(value, datetime):
            return value
        if isinstance(value, (int, float)):
            try:
                return datetime.fromtimestamp(value, tz=timezone.utc)
            except Exception:
                return None
        if isinstance(value, str):
            # Try ISO format
            for fmt in ("%Y-%m-%dT%H:%M:%S.%fZ", "%Y-%m-%dT%H:%M:%SZ", "%Y-%m-%dT%H:%M:%S"):
                try:
                    dt = datetime.strptime(value, fmt)
                    return dt.replace(tzinfo=timezone.utc)
                except ValueError:
                    pass
            # Try parsing as Unix timestamp
            try:
                return datetime.fromtimestamp(float(value), tz=timezone.utc)
            except (ValueError, OSError):
                return None
        return None

    def _trailer(self, commit: Any, name: str, default: str = "") -> str:
        """Extract a git trailer from a commit (e.g. Entire-Session)."""
        try:
            for trailer in commit.message.strip().split("\n"):
                if trailer.startswith(f"{name}: "):
                    return trailer[len(name) + 2 :].strip()
        except Exception:
            pass
        return default

    def _extract_files_from_commit(self, commit: Any) -> list[str]:
        """Extract file paths changed in a commit."""
        files: list[str] = []
        try:
            for parent in commit.parents:
                diff = parent.diff(commit)
                for d in diff:
                    if d.a_path:
                        files.append(d.a_path)
                    if d.b_path and d.b_path != d.a_path:
                        files.append(d.b_path)
        except Exception:
            pass
        return list(dict.fromkeys(files))  # Dedupe

    def _is_git_available(self) -> bool:
        """Check if gitpython is available and the repo is valid."""
        if self._git_available is not None:
            return self._git_available
        try:
            import git  # noqa: F401
            import git.exc

            git.Repo(str(self.repo_path))
            self._git_available = True
        except Exception:
            self._git_available = False
        return self._git_available

"""Intent vs Implementation analysis.

Compares what the user asked for (from transcript prompts) against what the
agent actually changed (from checkpoint file lists and commit messages).
"""
from dataclasses import dataclass

from app.adapter.models import Session, TranscriptEntry


@dataclass
class IntentVsImplResult:
    """Result of comparing user intent to actual implementation."""

    intent: str  # The user's original request
    implementation_summary: str  # What the agent actually did
    alignment_score: float  # 0.0–1.0: how well they match
    gaps: list[str]  # Things asked for but not delivered
    surprises: list[str]  # Things done that weren't in the intent


def extract_intent(transcript: list[TranscriptEntry]) -> str:
    """Pull the first user prompt from a transcript."""
    for entry in transcript:
        if entry.role == "user" and entry.content:
            if isinstance(entry.content, str) and entry.content.strip():
                return entry.content.strip()
    return ""


def extract_file_actions(transcript: list[TranscriptEntry]) -> dict[str, list[str]]:
    """Infer file actions from transcript tool calls.

    Returns dict with keys: 'created', 'modified', 'deleted', 'read'
    """
    created: list[str] = []
    modified: list[str] = []
    deleted: list[str] = []
    read: list[str] = []

    for entry in transcript:
        if entry.is_tool_use and entry.tool_name in ("Write", "Edit", "Bash"):
            tool_input = entry.tool_input or {}
            if isinstance(tool_input, dict):
                if entry.tool_name == "Write" and "file_path" in tool_input:
                    created.append(tool_input["file_path"])
                elif entry.tool_name == "Bash":
                    cmd = str(tool_input.get("command", ""))
                    if "rm " in cmd and ".go" in cmd:
                        deleted.append(cmd.split("rm ")[-1].split()[0])

        if entry.is_tool_result and entry.tool_name == "Read":
            tool_input = entry.tool_input or {}
            if isinstance(tool_input, dict) and "file_path" in tool_input:
                read.append(tool_input["file_path"])

    return {"created": created, "modified": modified, "deleted": deleted, "read": read}


def keyword_overlap(intent: str, message: str, files: list[str]) -> float:
    """Simple keyword overlap score between intent and implementation."""
    if not intent or not (message or files):
        return 0.5  # Unknown

    intent_words = set(intent.lower().split())
    impl_words = set()
    if message:
        impl_words.update(message.lower().split())
    for f in files:
        impl_words.update(f.lower().replace("/", " ").replace("_", " ").split())

    # Remove common stopwords
    stopwords = {
        "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for",
        "of", "with", "by", "from", "is", "are", "was", "were", "be", "been",
        "being", "have", "has", "had", "do", "does", "did", "will", "would",
        "should", "could", "can", "may", "might", "must", "i", "you", "we",
        "they", "it", "this", "that", "these", "those", "my", "your", "our",
    }
    intent_words -= stopwords
    impl_words -= stopwords

    if not intent_words:
        return 0.5

    overlap = len(intent_words & impl_words)
    return min(1.0, overlap / len(intent_words))


def compare_intent_vs_impl(session: Session) -> IntentVsImplResult:
    """Compare what the user asked for against what the agent delivered."""
    intent = extract_intent(session.transcript)
    if not intent:
        intent = session.description

    all_files = list(session.all_files_changed)
    message_parts = [cp.message for cp in session.checkpoints if cp.message]
    impl_summary = "; ".join(message_parts[:3]) if message_parts else ""

    gaps: list[str] = []
    surprises: list[str] = []

    # Simple heuristic: look for common request patterns in intent
    intent_lower = intent.lower()
    file_actions = extract_file_actions(session.transcript)

    # Check for creation requests vs actual creates
    if "add" in intent_lower or "new" in intent_lower or "create" in intent_lower:
        expected_action = "create"
    elif "fix" in intent_lower or "bug" in intent_lower:
        expected_action = "fix"
    elif "remove" in intent_lower or "delete" in intent_lower:
        expected_action = "delete"
    elif "update" in intent_lower or "change" in intent_lower:
        expected_action = "update"
    else:
        expected_action = "explore"

    # Check alignment
    if expected_action == "create" and not file_actions["created"]:
        gaps.append("User requested creation but no files were created")
    elif expected_action == "fix" and not all_files:
        gaps.append("User requested a fix but no files were modified")

    # Check for unexpected file changes
    unexpected_dirs = ["test", "tests", "docs", "migrations", "scripts"]
    unexpected = [
        f for f in all_files
        if any(f.startswith(d + "/") for d in unexpected_dirs)
        and f"{d}/" not in intent_lower
    ]
    if unexpected:
        surprises.append(f"Modified support files not mentioned in intent: {', '.join(unexpected[:5])}")

    alignment = keyword_overlap(intent, impl_summary, all_files)

    return IntentVsImplResult(
        intent=intent[:500],  # Truncate long prompts
        implementation_summary=impl_summary,
        alignment_score=alignment,
        gaps=gaps,
        surprises=surprises,
    )

"""Unfinished work detection.

Looks for patterns in transcripts and file changes that suggest incomplete work:
- TODO/FIXME comments
- Empty function bodies
- Failed tool calls
- Repeated retries on the same tool
- Partial file writes
"""
import re
from dataclasses import dataclass

from app.adapter.models import Session


@dataclass
class UnfinishedWorkResult:
    """Result of unfinished work analysis."""

    todos: list[str]  # TODO/FIXME comments found
    retries: list[str]  # Tool calls that were retried
    abandoned: list[str]  # Files that were started but not committed
    partial: list[str]  # Functions/methods that may be incomplete
    confidence: float  # 0.0–1.0: confidence that work is incomplete


def detect_todos(transcript_text: str) -> list[str]:
    """Extract TODO/FIXME/HACK comments from transcript content."""
    patterns = [
        r"#\s*TODO[:\s].*",
        r"#\s*FIXME[:\s].*",
        r"#\s*HACK[:\s].*",
        r"#\s*XXX[:\s].*",
        r"//\s*TODO[:\s].*",
        r"//\s*FIXME[:\s].*",
    ]

    todos: list[str] = []
    for pattern in patterns:
        for match in re.finditer(pattern, transcript_text, re.IGNORECASE | re.MULTILINE):
            todos.append(match.group(0).strip()[:200])

    return list(dict.fromkeys(todos))[:20]  # Dedupe and limit


def detect_retries(transcript) -> list[str]:
    """Find tool calls that were retried multiple times."""
    if not transcript:
        return []

    # Count tool uses by name
    tool_counts: dict[str, int] = {}
    for entry in transcript:
        if entry.is_tool_use and entry.tool_name:
            tool_counts[entry.tool_name] = tool_counts.get(entry.tool_name, 0) + 1

    # Tools called 3+ times suggest retry loops
    retries: list[str] = []
    for tool, count in tool_counts.items():
        if count >= 3:
            retries.append(f"{tool} called {count} times (possible retry loop)")

    return retries


def detect_partial_impls(transcript) -> list[str]:
    """Look for tool calls that may indicate partial implementations.

    Patterns:
    - Write/Edit calls with TODO comments in the content
    - Functions with 'pass' or '...' as body
    """
    partial: list[str] = []
    for entry in transcript:
        if entry.is_tool_use and entry.tool_name in ("Write", "Edit"):
            tool_input = entry.tool_input or {}
            content = ""
            if isinstance(tool_input, dict):
                content = str(tool_input.get("content", ""))

            if "..." in content and "def " in content:
                # Python: def foo(): ...
                partial.append("Python function with '...' body")
                break
            if re.search(r"func\s+\w+\(.*\)\s*\{\s*\}", content):
                # Go: empty function
                partial.append("Empty Go function body")
                break

    return partial


def detect_unfinished_work(session: Session) -> UnfinishedWorkResult:
    """Analyze a session for signs of incomplete work."""
    # Collect all text content from transcript
    transcript_text = ""
    for entry in session.transcript:
        if isinstance(entry.content, str):
            transcript_text += entry.content + "\n"
        elif entry.is_tool_use and entry.tool_input:
            transcript_text += str(entry.tool_input) + "\n"

    todos = detect_todos(transcript_text)
    retries = detect_retries(session.transcript)
    partial = detect_partial_impls(session.transcript)

    # Detect abandoned files: started but not in any checkpoint
    abandoned: list[str] = []
    if session.transcript:
        files_in_transcript = set()
        for entry in session.transcript:
            if entry.is_tool_use and entry.tool_input:
                path = entry.tool_input.get("file_path")
                if path:
                    files_in_transcript.add(path)

        committed_files = set(session.all_files_changed)
        abandoned = list(files_in_transcript - committed_files)[:10]

    # Confidence: how sure are we this is unfinished?
    confidence = 0.0
    if todos:
        confidence += 0.4
    if retries:
        confidence += 0.3
    if partial:
        confidence += 0.2
    if abandoned:
        confidence += 0.1
    if session.status == "active":
        confidence += 0.1  # Still running, may be unfinished by definition

    confidence = min(1.0, confidence)

    return UnfinishedWorkResult(
        todos=todos,
        retries=retries,
        abandoned=abandoned,
        partial=partial,
        confidence=confidence,
    )

"""Handoff readiness assessment.

Determines whether a session's work is ready to be handed off (merged,
deployed, or picked up by another developer). Considers:
- Whether there are obvious blockers (errors, TODOs, unfinished work)
- Whether the implementation matches the intent
- Whether the session has been formally ended
"""
from dataclasses import dataclass

from app.adapter.models import Session
from app.analysis.intent_vs_impl import compare_intent_vs_impl
from app.analysis.unfinished_work import detect_unfinished_work


@dataclass
class HandoffReadiness:
    """Handoff readiness assessment."""

    ready: bool
    confidence: float  # 0.0–1.0: how confident in the assessment
    blockers: list[str]  # Things that must be resolved
    suggestions: list[str]  # Things to improve before handoff
    summary: str


def assess_handoff_readiness(session: Session) -> HandoffReadiness:
    """Assess whether a session is ready to be handed off."""
    blockers: list[str] = []
    suggestions: list[str] = []

    # Check 1: Session must be ended (not still active)
    if session.status == "active":
        blockers.append("Session is still active")
    elif session.status == "unknown":
        suggestions.append("Session end time not recorded — verify completion")

    # Check 2: Intent vs implementation alignment
    intent_result = compare_intent_vs_impl(session)
    if intent_result.alignment_score < 0.2:
        blockers.append(
            f"Low intent alignment ({intent_result.alignment_score:.0%}) — "
            f"implementation may not match user request"
        )
    elif intent_result.alignment_score < 0.4:
        suggestions.append(
            f"Weak intent alignment ({intent_result.alignment_score:.0%}) — "
            f"consider verifying with the user"
        )

    if intent_result.gaps:
        blockers.extend([f"Gap: {g}" for g in intent_result.gaps])

    # Check 3: Unfinished work
    unfinished = detect_unfinished_work(session)
    if unfinished.todos:
        blockers.append(f"{len(unfinished.todos)} TODO/FIXME comments remain")
    if unfinished.retries:
        suggestions.append(
            f"Retry loops detected: {', '.join(unfinished.retries[:3])}"
        )
    if unfinished.abandoned:
        suggestions.append(
            f"{len(unfinished.abandoned)} files started but not committed"
        )
    if unfinished.partial:
        blockers.append(
            f"Partial implementations: {', '.join(unfinished.partial)}"
        )

    # Check 4: At least one checkpoint (some evidence of progress)
    if session.total_checkpoints == 0:
        suggestions.append("No checkpoints on record — verify work actually happened")

    # Check 5: Has the session been formally ended?
    if not session.end_time and session.status != "active":
        suggestions.append("Session has no end time recorded")

    # Compute confidence based on data quality
    confidence = 0.5
    if session.transcript:
        confidence += 0.2
    if session.checkpoints:
        confidence += 0.2
    if session.start_time:
        confidence += 0.05
    if session.end_time:
        confidence += 0.05

    confidence = min(1.0, confidence)

    # Ready if no blockers
    ready = len(blockers) == 0

    # Build summary
    if ready:
        if not suggestions:
            summary = "Ready for handoff. All clear."
        else:
            summary = f"Ready, with {len(suggestions)} suggestion(s) for improvement."
    else:
        summary = f"Not ready: {len(blockers)} blocker(s) need attention."

    return HandoffReadiness(
        ready=ready,
        confidence=confidence,
        blockers=blockers,
        suggestions=suggestions,
        summary=summary,
    )

